import axios from "axios";

const TMDB_API_KEY = "b56be59cfcfc26fbad50e51fb6341736";
const BASE_URL = "https://api.themoviedb.org/3";

// 🎯 예외 영화 movieId 매핑
const MOVIE_ID_EXCEPTIONS = {
  "인생은 아름다워_1997": 637,    // 이탈리아 영화
  "청설_2010": 49629,             // 대만 영화
};

// 🔍 제목으로 TMDB movieId 검색 (국가 제한 없음)
export const searchMovieIdFromTMDB = async (movieTitle, openDate, nation = "") => {
  try {
    const response = await axios.get(`${BASE_URL}/search/movie`, {
      params: {
        api_key: TMDB_API_KEY,
        query: movieTitle,
        language: "ko-KR",
        primary_release_year: openDate?.slice(0, 4),
      },
    });

    const results = response.data.results;
    if (results.length === 0) return null;

    // 후보 점수 계산
    const scoreMovie = (movie) => {
      let score = 0;
      if (movie.release_date === openDate) score += 3;
      else if (movie.release_date?.startsWith(openDate?.slice(0, 4))) score += 2;

      // 국가 언어 기반 비교
      if (nation === "한국" && movie.original_language === "ko") score += 2;
      else if (nation !== "한국" && movie.original_language !== "ko") score += 2;

      return score;
    };

    const sorted = results
      .map((m) => ({ ...m, __score: scoreMovie(m) }))
      .sort((a, b) => b.__score - a.__score);

    const target = sorted[0];

    if (
      openDate &&
      target?.release_date &&
      Math.abs(new Date(openDate) - new Date(target.release_date)) >
        1000 * 60 * 60 * 24 * 365
    ) {
      return null;
    }

    return target.id;
  } catch (error) {
    console.error("TMDB movieId 검색 실패:", error);
    return null;
  }
};

// 🖼️ TMDB movieId로 포스터 경로 반환
export const getMoviePosterById = async (movieId) => {
  try {
    const response = await axios.get(`${BASE_URL}/movie/${movieId}`, {
      params: {
        api_key: TMDB_API_KEY,
        language: "ko-KR",
      },
    });

    const movie = response.data;
    return movie.poster_path
      ? `https://image.tmdb.org/t/p/w780${movie.poster_path}`
      : movie.backdrop_path
      ? `https://image.tmdb.org/t/p/w780${movie.backdrop_path}`
      : "https://via.placeholder.com/120x170?text=No+Image";
  } catch (error) {
    console.error("TMDB 포스터 조회 실패:", error);
    return "https://via.placeholder.com/120x170?text=No+Image";
  }
};

// ✅ 최적화된 TMDB 포스터 가져오기 함수
export const getPosterFromTMDB = async (movieTitle, openDate, options = {}) => {
  const { directorName = "", nation = "" } = options;
  const key = `${movieTitle}_${openDate?.slice(0, 4)}`;

  // 1️⃣ 예외 등록된 movieId 우선 사용
  if (MOVIE_ID_EXCEPTIONS[key]) {
    return await getMoviePosterById(MOVIE_ID_EXCEPTIONS[key]);
  }

  // 2️⃣ 검색 기반으로 movieId 조회
  const movieId = await searchMovieIdFromTMDB(movieTitle, openDate, nation);
  if (!movieId) return "https://via.placeholder.com/120x170?text=No+Image";
  return await getMoviePosterById(movieId);
};
